    {
      "feature_name": "Contextual Insights",
      "description": "Receive alerts if a restaurant's average tip is significantly higher or lower than the city norm, indicating potential service quality issues."
    },
    {
      "feature_name": "Cultural Mode",
      "description": "A dedicated section explaining local tipping laws and customs for international travelers."
    },
    {
      "feature_name": "Privacy-First Aggregation",
      "description": "All data is anonymized and aggregated; individual user tips are never shared."
    }
